            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            r0, r1 = min(x for x, y in cells), max(x for x, y in cells)
            c0, c1 = min(y for x, y in cells), max(y for x, y in cells)
            objects.append((color, set(cells), r0, c0, r1, c1))

    frames = []
    sources = []
    for color, cells, r0, c0, r1, c1 in objects:
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if r1 > r0 + 1 and c1 > c0 + 1 and border <= cells:
            frames.append((color, r0, c0, r1, c1))
        else:
            bitmap = [[grid[r][c] == color for c in range(r0, r1 + 1)]
                      for r in range(c0, c1 + 1)]
            # Correct orientation: rows then columns within the object's box.
            bitmap = [[grid[r][c] == color for c in range(c0, c1 + 1)]
                      for r in range(r0, r1 + 1)]
            sources.append((color, bitmap))

    out = [row[:] for row in grid]
    if not sources:
        return out
    source_color, bitmap = max(sources, key=lambda x: sum(sum(row) for row in x[1]))
    sh, sw = len(bitmap), len(bitmap[0])

    for color, r0, c0, r1, c1 in frames:
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        for i in range(ih):
            for j in range(iw):
                si = min(sh - 1, i * sh // ih)
                sj = min(sw - 1, j * sw // iw)
                out[r0 + 1 + i][c0 + 1 + j] = color if bitmap[si][sj] else 0
    return out
